/**
 * Body received but unable to read as UTF-8. Raw bytes, base64-encoded.
 */
export const zVulnScannerBolaBodyResponseBytes = z.object({
    contents: z.string(),
    kind: z.enum(['bytes']),
    truncated: z.boolean()
}).register(z.globalRegistry, {
    description: 'Body received but unable to read as UTF-8. Raw bytes, base64-encoded.'
});

/**
 * Body received as valid JSON.
 */
export const zVulnScannerBolaBodyResponseJson = z.object({
    contents: z.string(),
    kind: z.enum(['json']),
    truncated: z.boolean()
}).register(z.globalRegistry, {
    description: 'Body received as valid JSON.'
});

/**
 * No body was received.
 */
export const zVulnScannerBolaBodyResponseNotFound = z.object({
    kind: z.enum(['not_found'])
}).register(z.globalRegistry, {
    description: 'No body was received.'
});

/**
 * Body received as valid UTF-8 text but not valid JSON.
 */
export const zVulnScannerBolaBodyResponseText = z.object({
    contents: z.string(),
    kind: z.enum(['text']),
    truncated: z.boolean()
}).register(z.globalRegistry, {
    description: 'Body received as valid UTF-8 text but not valid JSON.'
});

/**
 * HTTP response body preview.
 */
export const zVulnScannerBolaBodyResponse = z.discriminatedUnion('kind', [
    zVulnScannerBolaBodyResponseNotFound.extend({ kind: z.literal('not_found') }),
    zVulnScannerBolaBodyResponseBytes.extend({ kind: z.literal('bytes') }),
    zVulnScannerBolaBodyResponseText.extend({ kind: z.literal('text') }),
    zVulnScannerBolaBodyResponseJson.extend({ kind: z.literal('json') })
]);

/**
 * Identifies the role a request was made with. The credential set governs this role. `owner` is the resource owner, `attacker` attempts to access resources.
 */
export const zVulnScannerBolaCredentialRole = z.enum(['owner', 'attacker']).register(z.globalRegistry, {
    description: 'Identifies the role a request was made with. The credential set governs this role. `owner` is the resource owner, `attacker` attempts to access resources.'
});

/**
 * Credential set references for a BOLA scan. The scanner uses the
 * `owner` credentials for legitimate requests and the `attacker`
 * credentials to attempt unauthorized access.
 *
 */
export const zVulnScannerBolaCredentialSets = z.object({
    attacker: z.uuid().register(z.globalRegistry, {
        description: 'Credential set ID for the attacker.'
    }),
    owner: z.uuid().register(z.globalRegistry, {
        description: 'Credential set ID for the resource owner.'
    })
}).register(z.globalRegistry, {
    description: 'Credential set references for a BOLA scan. The scanner uses the\n`owner` credentials for legitimate requests and the `attacker`\ncredentials to attempt unauthorized access.\n'
});

/**
 * Range of HTTP status codes.
 */
export const zVulnScannerBolaHttpStatusRange = z.object({
    max: z.int().gte(0).lte(65535).register(z.globalRegistry, {
        description: 'Maximum (inclusive) status code of the range.'
    }),
    min: z.int().gte(0).lte(65535).register(z.globalRegistry, {
        description: 'Minimum (inclusive) status code of the range.'
    })
}).register(z.globalRegistry, {
    description: 'Range of HTTP status codes.'
});

/**
 * Assert that an HTTP status code is within a range, e.g. to assert success for the 2xx range, or expected failure for the 4xx/5xx range.
 */
export const zVulnScannerBolaAssertionKind = z.object({
    parameters: zVulnScannerBolaHttpStatusRange,
    type: z.enum(['http_status_within_range'])
}).register(z.globalRegistry, {
    description: 'Assert that an HTTP status code is within a range, e.g. to assert success for the 2xx range, or expected failure for the 4xx/5xx range.'
});

/**
 * HTTP method.
 */
export const zVulnScannerBolaMethod = z.enum([
    'GET',
    'DELETE',
    'PATCH',
    'POST',
    'PUT'
]).register(z.globalRegistry, {
    description: 'HTTP method.'
});

/**
 * Outcome of an assertion. `ok` means the assertion passed, `fail` means the assertion failed, `inconclusive` means the scanner could not evaluate the assertion.
 */
export const zVulnScannerBolaOutcome = z.enum([
    'ok',
    'fail',
    'inconclusive'
]).register(z.globalRegistry, {
    description: 'Outcome of an assertion. `ok` means the assertion passed, `fail` means the assertion failed, `inconclusive` means the scanner could not evaluate the assertion.'
});

/**
 * Assertion that was made against the received response.
 */
export const zVulnScannerBolaTestAssertion = z.object({
    description: z.string().register(z.globalRegistry, {
        description: 'Human-readable description of the assertion, explaining what was checked.'
    }),
    kind: zVulnScannerBolaAssertionKind,
    observed: z.int().nullable(),
    outcome: zVulnScannerBolaOutcome
}).register(z.globalRegistry, {
    description: 'Assertion that was made against the received response.'
});

/**
 * Credential set that was used.
 */
export const zVulnScannerBolaTestCredentialSet = z.object({
    id: z.uuid().register(z.globalRegistry, {
        description: 'ID of the credential set.'
    }),
    role: zVulnScannerBolaCredentialRole
}).register(z.globalRegistry, {
    description: 'Credential set that was used.'
});

/**
 * Error that occurred during a test.
 */
export const zVulnScannerBolaTestError = z.object({
    description: z.string().register(z.globalRegistry, {
        description: 'Human-readable error description.'
    }),
    error_code: z.int().gte(0).max(4294967295, { error: 'Invalid value: Expected uint32 to be <= 4294967295' }).nullish()
}).register(z.globalRegistry, {
    description: 'Error that occurred during a test.'
});

/**
 * HTTP response that was received.
 */
export const zVulnScannerBolaTestResponse = z.object({
    body: zVulnScannerBolaBodyResponse,
    header_names: z.array(z.string()).register(z.globalRegistry, {
        description: 'Names of headers that were received.'
    }),
    status: z.int().gte(0).lte(65535).register(z.globalRegistry, {
        description: 'HTTP status code.'
    }),
    status_text: z.string().nullish()
}).register(z.globalRegistry, {
    description: 'HTTP response that was received.'
});

/**
 * A variable to capture from the response body.
 */
export const zVulnScannerBolaVariableCapture = z.object({
    json_path: z.string().register(z.globalRegistry, {
        description: 'JSONPath expression used for capture, e.g. `"$.id"`.'
    }),
    name: z.string().register(z.globalRegistry, {
        description: 'Variable name, e.g. `"resource_id"`.'
    })
}).register(z.globalRegistry, {
    description: 'A variable to capture from the response body.'
});

/**
 * HTTP request that was made.
 */
export const zVulnScannerBolaTestRequest = z.object({
    body: z.record(z.string(), z.unknown()).nullish(),
    credential_set: zVulnScannerBolaTestCredentialSet,
    header_names: z.array(z.string()).register(z.globalRegistry, {
        description: 'Names of headers that were sent.'
    }),
    method: zVulnScannerBolaMethod,
    url: z.url().register(z.globalRegistry, {
        description: 'Exact and full URL (including host, query parameters) that was requested.'
    }),
    variable_captures: z.array(zVulnScannerBolaVariableCapture).register(z.globalRegistry, {
        description: 'Variable captures requested for this step.'
    })
}).register(z.globalRegistry, {
    description: 'HTTP request that was made.'
});

/**
 * A single step in a test.
 */
export const zVulnScannerBolaTestStep = z.object({
    assertions: z.array(zVulnScannerBolaTestAssertion).register(z.globalRegistry, {
        description: 'Assertions that were made against the received response.'
    }),
    errors: z.array(zVulnScannerBolaTestError).register(z.globalRegistry, {
        description: 'Errors the step encountered that may explain absent or incomplete fields.'
    }).optional(),
    request: zVulnScannerBolaTestRequest.nullish(),
    response: zVulnScannerBolaTestResponse.nullish()
}).register(z.globalRegistry, {
    description: 'A single step in a test.'
});

/**
 * A verdict. `ok` means the scan passed, `warning` means the scan detected issues, `inconclusive` means errors prevented the scanner from reaching an accurate verdict.
 */
export const zVulnScannerBolaVerdict = z.enum([
    'ok',
    'warning',
    'inconclusive'
]).register(z.globalRegistry, {
    description: 'A verdict. `ok` means the scan passed, `warning` means the scan detected issues, `inconclusive` means errors prevented the scanner from reaching an accurate verdict.'
});

/**
 * Overall report summary.
 */
export const zVulnScannerBolaReportSummary = z.object({
    verdict: zVulnScannerBolaVerdict
}).register(z.globalRegistry, {
    description: 'Overall report summary.'
});

/**
 * Result of a single test.
 */
export const zVulnScannerBolaTest = z.object({
    preflight_errors: z.array(zVulnScannerBolaTestError).register(z.globalRegistry, {
        description: 'Errors that prevented step execution.'
    }).optional(),
    steps: z.array(zVulnScannerBolaTestStep).register(z.globalRegistry, {
        description: 'Steps that were executed.'
    }),
    verdict: zVulnScannerBolaVerdict
}).register(z.globalRegistry, {
    description: 'Result of a single test.'
});

/**
 * Version 1 of the BOLA vulnerability scan report.
 */
export const zVulnScannerBolaReportV1 = z.object({
    summary: zVulnScannerBolaReportSummary,
    tests: z.array(zVulnScannerBolaTest).register(z.globalRegistry, {
        description: 'List of tests that were run.'
    })
}).register(z.globalRegistry, {
    description: 'Version 1 of the BOLA vulnerability scan report.'
});

/**
 * A BOLA vulnerability scan report, versioned for future evolution.
 */
export const zVulnScannerBolaReport = z.object({
    report: zVulnScannerBolaReportV1,
    report_schema_version: z.enum(['v1']).register(z.globalRegistry, {
        description: 'Version of the report schema.'
    })
}).register(z.globalRegistry, {
    description: 'A BOLA vulnerability scan report, versioned for future evolution.'
});

