export const zWafManagedRulesBaseWritable = z.unknown();

export const zWafManagedRulesGroupWritable = z.record(z.string(), z.unknown());

export const zWafManagedRulesSchemasBaseWritable = zWafManagedRulesBaseWritable;

/**
 * Anomaly detection WAF rule
 *
 * When triggered, anomaly detection WAF rules contribute to an overall threat score that will determine if a request is considered malicious. You can configure the total scoring threshold through the 'sensitivity' property of the WAF package.
 */
export const zWafManagedRulesAnomalyRuleWritable = zWafManagedRulesSchemasBaseWritable.and(z.object({
    mode: zWafManagedRulesModeAnomaly
}));

export const zWafManagedRulesSchemasGroupWritable = zWafManagedRulesGroupWritable.and(z.object({
    mode: zWafManagedRulesMode
}));

export const zWafManagedRulesRuleGroupResponseCollectionWritable = zWafManagedRulesApiResponseCollection.and(z.object({
    result: z.array(zWafManagedRulesSchemasGroupWritable).optional()
}));

/**
 * Traditional (allow) WAF rule
 *
 * When triggered, traditional WAF rules cause the firewall to immediately act on the request based on the rule configuration. An 'allow' rule will immediately allow the request and no other rules will be processed.
 */
export const zWafManagedRulesTraditionalAllowRuleWritable = zWafManagedRulesBaseWritable.and(z.object({
    mode: zWafManagedRulesModeAllowTraditional
}));

/**
 * Traditional (deny) WAF rule
 *
 * When triggered, traditional WAF rules cause the firewall to immediately act upon the request based on the configuration of the rule. A 'deny' rule will immediately respond to the request based on the configured rule action/mode (for example, 'block') and no other rules will be processed.
 */
export const zWafManagedRulesTraditionalDenyRuleWritable = zWafManagedRulesBaseWritable.and(z.object({
    mode: zWafManagedRulesModeDenyTraditional
}));

export const zWafManagedRulesRuleWritable = z.union([
    zWafManagedRulesAnomalyRuleWritable,
    zWafManagedRulesTraditionalDenyRuleWritable,
    zWafManagedRulesTraditionalAllowRuleWritable
]);

export const zWafManagedRulesRuleResponseCollectionWritable = zWafManagedRulesApiResponseCollection.and(z.object({
    result: z.array(zWafManagedRulesRuleWritable).optional()
}));

